{
  "name": "opencode-gotcha",
  "version": "0.1.1",
  "description": "Память проверенных обходов и рабочих приёмов для повторяющихся задач в OpenCode.",
  "type": "module",
  "main": "index.js",
  "exports": {
    ".": "./index.js",
    "./server": "./v2/index.js",
    "./v2": "./v2/index.js",
    "./store": "./src/store.js",
    "./scope": "./src/scope.js"
  },
  "files": [
    "index.js",
    "v2",
    "src",
    "LICENSE"
  ],
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.21 <2"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": { "optional": true }
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.21"
  },
  "scripts": {
    "test": "node --test test/*.test.mjs",
    "smoke:package": "node scripts/package-smoke.mjs",
    "smoke:v2": "node scripts/v2-smoke.mjs",
    "release": "node scripts/release.mjs",
    "check": "node --check index.js && node --check v2/index.js && node --check src/markdown.js && node --check src/store.js && node --check src/lock.js && node --check src/scope.js && node --check src/origin.js && node --check src/tools.js && node --check src/tools-v1.js && node --check src/directive.js && node --check src/context.js && node --check scripts/release.mjs"
  },
  "repository": {
    "type": "git",
    "url": "git+https://git.sourcecraft.dev/voischev/opencode-gotcha.git"
  },
  "homepage": "https://www.npmjs.com/package/opencode-gotcha",
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "memory",
    "gotcha"
  ],
  "license": "MIT"
}
